 "mainEntity": [
  {
   "@type": "Question",
   "name": "외출할 때 보일러를 꺼도 되나요?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "단열이 잘 되는 집에서 튼튼한 성견이 혼자 몇 시간 있는 정도라면 괜찮을 수 있어요. 하지만 한겨울이거나 퍼피·노령견·소형견·단모종이면 외출 모드나 낮은 온도로 켜 두는 쪽을 권해요."
   }
  },
  {
   "@type": "Question",
   "name": "강아지에게 적당한 실내 온도는 몇 도인가요?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "보통 18~22도 정도를 편하게 느낀다고 알려져 있어요. 추위에 약한 아이는 조금 더 따뜻하게, 이중모가 두꺼운 진돗개 같은 아이는 조금 서늘해도 괜찮아요."
   }
  },
  {
   "@type": "Question",
   "name": "보일러를 너무 세게 틀면 안 좋나요?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "네. 바닥 난방은 바닥이 뜨거워져서 오래 누워 있으면 저온 화상이 생길 수 있고, 실내가 건조해져요. 강아지가 시원한 곳으로 옮겨 갈 수 있게 해 주세요."
   }
  },
  {
   "@type": "Question",
   "name": "전기장판이나 히터를 켜 두고 나가도 되나요?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "혼자 있을 때는 권하지 않아요. 전선을 씹거나 가까이 붙어 있다가 화상을 입을 수 있고, 화재 위험도 있어요."
   }
  }
 ]
}
